magazine-cover.variantCss:
/* --- Magazine Cover：盖满墨章的工坊扉页 --- */
.wemd-magazine-cover[data-variant="pixel-arcade"] {
  padding: 2rem 1.25rem 2.5rem;
  background:
    /* 像素格纸底纹：多层细线渐变模拟 graph paper（合并伪元素，微信兼容） */
    linear-gradient(#dccfb4 1px, transparent 1px),
    linear-gradient(90deg, #dccfb4 1px, transparent 1px),
    #f5efe0;
  background-size: 16px 16px, 16px 16px, auto;
  border: 1px solid #dccfb4;
  border-radius: 4px;
  text-align: center;
}
.wemd-magazine-cover[data-variant="pixel-arcade"] .wemd-mc-top-bar {
  display: block;
  width: 56px;
  height: 3px;
  margin: 0 auto 1rem;
  background: #e8590c; /* 油墨挂牌 */
}
.wemd-magazine-cover[data-variant="pixel-arcade"] .wemd-mc-title {
  font-family: "SF Mono", "Cascadia Code", Consolas, "Courier New", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  font-size: 1.5rem;
  font-weight: 800;
  line-height: 1.4;
  color: #2b2420;
}
.wemd-magazine-cover[data-variant="pixel-arcade"] .wemd-mc-subtitle {
  margin-top: 0.5rem;
  font-size: 0.85rem;
  letter-spacing: 0.08em;
  color: #0b7285; /* pixel 青蓝副题 */
}
.wemd-magazine-cover[data-variant="pixel-arcade"] .wemd-mc-divider {
