image-text-row.variantCss:
/* --- Image Text Row：图文左右混排 --- */
.wemd-image-text-row[data-variant="pixel-arcade"] {
  padding: 1.25rem 1.25rem;
}
.wemd-image-text-row[data-variant="pixel-arcade"] .wemd-component-body {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.wemd-image-text-row[data-variant="pixel-arcade"] .wemd-component-body > img {
  flex: 0 0 42%;
  width: 42%;
  border: 2px solid #b9a887;
  border-radius: 4px;
}

/* ============================================================
   Utility · 极简样式 · 低可见度 · 无装饰 · 无动画
   ============================================================ */

/* --- Divider --- */

image-grid.variantCss:
/* --- Image Grid：精灵表网格陈列 ---
   母题要求像素精灵表（sprite sheet）的规整排列。
.wemd-image-grid[data-variant="pixel-arcade"] .wemd-component-body {
  font-size: 0;
}
.wemd-image-grid[data-variant="pixel-arcade"] .wemd-component-body > img {
  display: inline-block;
  width: 48%;
  margin: 1%;
  border: 2px solid #b9a887; /* 硬边像素贴片 */
  vertical-align: top;
}

/* ============================================================
   Content · 标准容器 · 克制装饰 · 可读性优先 · 无动画
   ============================================================ */

/* --- Numbered Heading：手作工序编号 --- */

image-compare.variantCss:
/* --- Image Compare：像素前后对比 --- */
.wemd-image-compare[data-variant="pixel-arcade"] {
  padding: 1.25rem 1.25rem;
}
.wemd-image-compare[data-variant="pixel-arcade"] .wemd-component-body {
  display: flex;
  gap: 0.75rem;
}
.wemd-image-compare[data-variant="pixel-arcade"] .wemd-component-body > img {
  flex: 1 1 50%;
  width: 50%;
  border: 2px solid #b9a887; /* 硬边像素贴片 */
  border-radius: 4px;
}

/* --- Image Text Row：图文左右混排 --- */

resource-list.variantCss:
/* --- Resource List：工坊货架上的工具/素材清单 --- */
.wemd-resource-list[data-variant="pixel-arcade"] {
  padding: 1.5rem 1.25rem;
  background: #ece3cf;
  border: 1px solid #dccfb4;
  border-radius: 4px;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-header {
  display: block;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-top-bar {
  display: block;
  width: 56px;
  height: 3px;
  background: #e8590c; /* 清单挂牌 */
  margin-bottom: 0.75rem;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-title {
  font-family: "SF Mono", "Cascadia Code", Consolas, "Courier New", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  font-size: 1.05rem;
  font-weight: 700;
  color: #2b2420;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-subtitle {
  margin-top: 0.25rem;
  font-size: 0.85rem;
  color: #9a8f7d;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items {
  margin-top: 1rem;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-item {
  padding: 0.75rem 0;
  border-top: 1px solid #dccfb4; /* 逐项用上边框分隔（避免结构伪类） */
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-label {
  display: inline-block;
  padding: 1px 6px;
  font-size: 0.7rem;
  color: #0b7285; /* pixel 青蓝编号 */
  border: 1px solid #0b7285;
  border-radius: 2px;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-title {
  margin-top: 0.35rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #2b2420;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-desc {
  margin-top: 0.2rem;
  font-size: 0.85rem;
  line-height: 1.6;
  color: #5c5348;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-meta {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: #9a8f7d;
}
.wemd-resource-list[data-variant="pixel-arcade"] .wemd-rl-items-tag {
  margin-top: 0.35rem;
  font-size: 0.75rem;
  color: #e8590c; /* 油墨橙标签 */
}

/* --- Styled Table：格纸上的手写参数记录 --- */

styled-table.variantCss:
/* --- Styled Table：格纸上的手写参数记录 --- */
.wemd-styled-table[data-variant="pixel-arcade"] {
  padding: 1.5rem 1.25rem;
  background: #f5efe0;
  border: 1px solid #dccfb4;
  border-radius: 4px;
}
.wemd-styled-table[data-variant="pixel-arcade"] .wemd-sbt-top-bar {
  display: block;
  width: 56px;
  height: 3px;
  background: #e8590c; /* 表格挂牌 */
  margin-bottom: 0.75rem;
}
.wemd-styled-table[data-variant="pixel-arcade"] .wemd-sbt-table {
  border-collapse: collapse;
  width: 100%;
  font-family: "SF Mono", "Cascadia Code", Consolas, "Courier New", "Microsoft YaHei", "PingFang SC", "Noto Sans SC", sans-serif;
  font-size: 0.85rem;
  color: #5c5348;
}
.wemd-styled-table[data-variant="pixel-arcade"] .wemd-sbt-table th {
  padding: 0.5rem 0.4rem;
  text-align: left;
  font-weight: 700;
  color: #e8590c; /* 表头油墨橙 */
  border-bottom: 2px solid #e8590c;
}
.wemd-styled-table[data-variant="pixel-arcade"] .wemd-sbt-table td {
  padding: 0.5rem 0.4rem;
  border-bottom: 1px solid #dccfb4;
}

