divider-fancy.variantCss:
/* --- Divider Fancy：像素分隔 --- */
.wemd-divider-fancy[data-variant="pixel-arcade"] {
  height: 1px;
  background: #dccfb4;
}
.wemd-divider-fancy[data-variant="pixel-arcade"] .wemd-df-label {
  font-size: 0.7rem;
  color: #9a8f7d;
}

/* --- Section Divider --- */

divider.variantCss:
/* --- Divider --- */
.wemd-divider[data-variant="pixel-arcade"] {
  height: 1px;
  background: #dccfb4;
}

/* --- Divider Fancy：像素分隔 --- */

copyright-notice.variantCss:
/* --- Copyright Notice --- */
.wemd-copyright-notice[data-variant="pixel-arcade"] {
  font-size: 0.7rem;
  color: #9a8f7d;
}

/* ============================================================
   Stack：组件间距统一由容器控制
   组件不管理外部间距，所有 margin 由 Stack 统一分配。
   ============================================================ */
#wemd > [class] {
  margin-top: 0;
  margin-bottom: 1.5rem;
}
